/* @autogenerated */
package net.civeira.phylax.feature.oauth.client.application;

import java.time.Instant;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.client.domain.ClientDetails;
import net.civeira.phylax.feature.oauth.client.domain.exception.RequestObjectException;

/**
 * Claims of a signed request object (task 3.3); the signature is checked by the gateway.
 */
class RequestObjectVerifierUnitTest {

  private static final String ISSUER = "https://auth.example.com/oauth/openid/acme";
  private static final ClientDetails CLIENT = ClientDetails.builder().clientId("web")
      .allowedScopes(List.of("*")).allowedGrants(List.of("authorization_code")).build();

  private Map<String, Object> claims;
  private final Set<String> used = new HashSet<>();
  private RequestObjectVerifier verifier;

  @BeforeEach
  void setUp() {
    claims = new HashMap<>();
    claims.put("iss", "web");
    claims.put("aud", ISSUER);
    claims.put("exp", Instant.now().plusSeconds(300).getEpochSecond());
    claims.put("jti", "j-1");
    claims.put("redirect_uri", "https://app.example/cb");
    claims.put("scope", List.of("openid", "profile"));
    verifier = new RequestObjectVerifier((client, jwt, alg) -> Optional.of(claims),
        (tenant, clientId, purpose, jti, exp) -> used.add(jti));
  }

  private String error() {
    return Assertions.assertThrows(RequestObjectException.class,
        () -> verifier.verify("acme", ISSUER, CLIENT, "jwt")).getErrorCode();
  }

  @Test
  @DisplayName("A valid object becomes parameters, with the client id, and is used once")
  void valid_object_once() {
    Map<String, String> params = verifier.verify("acme", ISSUER, CLIENT, "jwt");

    Assertions.assertEquals("https://app.example/cb", params.get("redirect_uri"));
    Assertions.assertEquals("openid profile", params.get("scope"));
    Assertions.assertEquals("web", params.get("client_id"));
    Assertions.assertFalse(params.containsKey("jti"));
    Assertions.assertEquals("invalid_request_object", error(), "Replay");
  }

  @Test
  @DisplayName("Issuer, client id, audience and nesting are checked")
  void identity_claims() {
    claims.put("iss", "other");
    Assertions.assertEquals("invalid_request_object", error());
    claims.put("iss", "web");
    claims.put("client_id", "other");
    Assertions.assertEquals("invalid_request_object", error());
    claims.remove("client_id");
    claims.put("aud", List.of("https://other.example"));
    Assertions.assertEquals("invalid_request_object", error());
    claims.put("aud", List.of(ISSUER));
    claims.put("request_uri", "urn:x");
    Assertions.assertEquals("invalid_request_object", error());
  }

  @Test
  @DisplayName("Expired, not yet valid, too long lived or without jti: rejected without spending it")
  void time_and_jti() {
    claims.put("exp", Instant.now().minusSeconds(1).getEpochSecond());
    Assertions.assertEquals("invalid_request_object", error());
    claims.put("exp", Instant.now().plusSeconds(7200).getEpochSecond());
    Assertions.assertEquals("invalid_request_object", error(), "Lifetime over an hour");
    claims.put("exp", Instant.now().plusSeconds(300).getEpochSecond());
    claims.put("nbf", Instant.now().plusSeconds(600).getEpochSecond());
    Assertions.assertEquals("invalid_request_object", error());
    claims.remove("nbf");
    claims.remove("jti");
    Assertions.assertEquals("invalid_request_object", error());
    Assertions.assertTrue(used.isEmpty(), "Rejected objects never consume their jti");
  }
}
